import { writeFile } from "node:fs/promises";
import { join } from "node:path";

import { z } from "zod";

import { MediaToolError, runMediaTool } from "./tools";

// What the worker does with FFmpeg: read a file's properties, extract its audio for
// transcription, and render a clip (cut, reframe, optional burned-in subtitles). Every
// call is local-file only (`-protocol_whitelist file`, `file:` paths generated by us).
// Pure (no `server-only`): integration tests run it against real FFmpeg.

export interface MediaTools {
  readonly ffmpeg: string;
  readonly ffprobe: string;
  readonly threads: number;
}

export interface MediaInfo {
  readonly formatName: string;
  readonly durationMs: number;
  readonly hasVideo: boolean;
  readonly hasAudio: boolean;
  readonly width: number | null;
  readonly height: number | null;
  readonly fpsMilli: number | null;
  readonly videoCodec: string | null;
  readonly audioCodec: string | null;
}

const LOCAL_ONLY = ["-protocol_whitelist", "file"] as const;
const file = (path: string) => `file:${path}`;

const probeSchema = z.object({
  format: z.object({
    format_name: z.string().max(200),
    duration: z
      .string()
      .regex(/^\d+(\.\d+)?$/)
      .optional(),
  }),
  streams: z
    .array(
      z.object({
        codec_type: z.string().max(20),
        codec_name: z.string().max(40).optional(),
        width: z.number().int().positive().optional(),
        height: z.number().int().positive().optional(),
        avg_frame_rate: z.string().max(40).optional(),
        disposition: z.object({ attached_pic: z.number().optional() }).optional(),
      }),
    )
    .max(64),
});

function fpsMilli(rate: string | undefined): number | null {
  const match = /^(\d+)\/(\d+)$/.exec(rate ?? "");
  if (match === null) return null;
  const [num, den] = [Number(match[1]), Number(match[2])];
  if (den === 0 || num === 0) return null;
  return Math.round((num / den) * 1000);
}

/** Reads a file's container, duration and streams. Rejects files ffprobe cannot read. */
export async function probeMedia(
  tools: MediaTools,
  path: string,
  options: { readonly timeoutMs: number; readonly signal?: AbortSignal },
): Promise<MediaInfo> {
  const { stdout } = await runMediaTool(
    tools.ffprobe,
    [
      "-v",
      "error",
      ...LOCAL_ONLY,
      "-print_format",
      "json",
      "-show_format",
      "-show_streams",
      file(path),
    ],
    options,
  );
  let raw: unknown;
  try {
    raw = JSON.parse(stdout);
  } catch {
    throw new MediaToolError("failed", null, "unreadable probe output");
  }
  const parsed = probeSchema.safeParse(raw);
  if (!parsed.success) throw new MediaToolError("failed", null, "unexpected probe output");
  const { format, streams } = parsed.data;
  // A cover image inside an audio file is a "video" stream with attached_pic: not video.
  const video = streams.find(
    (stream) => stream.codec_type === "video" && stream.disposition?.attached_pic !== 1,
  );
  const audio = streams.find((stream) => stream.codec_type === "audio");
  const durationMs = Math.round(Number(format.duration ?? "0") * 1000);
  return {
    formatName: format.format_name,
    durationMs,
    hasVideo: video !== undefined,
    hasAudio: audio !== undefined,
    width: video?.width ?? null,
    height: video?.height ?? null,
    fpsMilli: fpsMilli(video?.avg_frame_rate),
    videoCodec: video?.codec_name ?? null,
    audioCodec: audio?.codec_name ?? null,
  };
}

/** Mono 16 kHz PCM WAV: what speech-to-text services expect. */
/**
 * One piece of the extracted 16 kHz WAV, as ~24 kbps mono Opus (Ogg): what is sent to an
 * external speech-to-text provider (ten minutes ≈ 1.8 MB).
 */
export async function encodeAudioPiece(
  tools: MediaTools,
  input: string,
  output: string,
  piece: { readonly startMs: number; readonly durationMs: number },
  options: { readonly timeoutMs: number; readonly signal?: AbortSignal },
): Promise<void> {
  await runMediaTool(
    tools.ffmpeg,
    [
      "-nostdin",
      "-hide_banner",
      "-v",
      "error",
      ...LOCAL_ONLY,
      "-ss",
      (piece.startMs / 1000).toFixed(3),
      "-t",
      (piece.durationMs / 1000).toFixed(3),
      "-i",
      file(input),
      "-vn",
      "-ac",
      "1",
      "-ar",
      "16000",
      "-c:a",
      "libopus",
      "-b:a",
      "24k",
      "-application",
      "voip",
      "-threads",
      String(tools.threads),
      "-f",
      "ogg",
      "-y",
      file(output),
    ],
    options,
  );
}

export async function extractAudio(
  tools: MediaTools,
  input: string,
  output: string,
  options: { readonly timeoutMs: number; readonly signal?: AbortSignal },
): Promise<void> {
  await runMediaTool(
    tools.ffmpeg,
    [
      "-nostdin",
      "-hide_banner",
      "-v",
      "error",
      ...LOCAL_ONLY,
      "-i",
      file(input),
      "-vn",
      "-ac",
      "1",
      "-ar",
      "16000",
      "-c:a",
      "pcm_s16le",
      "-threads",
      String(tools.threads),
      "-y",
      file(output),
    ],
    options,
  );
}

export type AspectRatio = "PORTRAIT_9_16" | "LANDSCAPE_16_9" | "SQUARE_1_1";

/** Output frame per aspect ratio (even sizes, H.264-friendly). */
export const OUTPUT_SIZES: Readonly<Record<AspectRatio, { width: number; height: number }>> = {
  PORTRAIT_9_16: { width: 720, height: 1280 },
  LANDSCAPE_16_9: { width: 1280, height: 720 },
  SQUARE_1_1: { width: 720, height: 720 },
};

const even = (value: number) => Math.max(2, Math.floor(value / 2) * 2);

/**
 * The crop that reframes a `width`×`height` source to the target aspect ratio: the
 * largest window of that ratio, moved horizontally by `cropX` (0 = left edge, 50 =
 * centre, 100 = right edge) — or centred vertically when the source is taller than the
 * target. A fixed, adjustable crop: no face or speaker tracking.
 */
export function reframeCrop(
  width: number,
  height: number,
  aspect: AspectRatio,
  cropX: number,
): { width: number; height: number; x: number; y: number } {
  const target = OUTPUT_SIZES[aspect];
  const ratio = target.width / target.height;
  const focus = Math.min(Math.max(cropX, 0), 100) / 100;
  if (width / height > ratio) {
    const cropWidth = even(Math.min(width, height * ratio));
    return {
      width: cropWidth,
      height: even(height),
      x: Math.round((width - cropWidth) * focus),
      y: 0,
    };
  }
  const cropHeight = even(Math.min(height, width / ratio));
  return {
    width: even(width),
    height: cropHeight,
    x: 0,
    y: Math.round((height - cropHeight) / 2),
  };
}

export interface SubtitleCue {
  readonly startMs: number;
  readonly endMs: number;
  readonly text: string;
}

function srtTime(ms: number): string {
  const total = Math.max(0, Math.round(ms));
  const h = Math.floor(total / 3_600_000);
  const m = Math.floor((total % 3_600_000) / 60_000);
  const s = Math.floor((total % 60_000) / 1000);
  const rest = total % 1000;
  const pad = (n: number, w = 2) => String(n).padStart(w, "0");
  return `${pad(h)}:${pad(m)}:${pad(s)},${pad(rest, 3)}`;
}

/** SubRip text; cue text is flattened to one line per cue (no markup is interpreted). */
export function toSrt(cues: readonly SubtitleCue[]): string {
  return cues
    .map((cue, index) => {
      const text = cue.text
        .replace(/[\r\n]+/g, " ")
        .replace(/[{}<>\\]/g, "")
        .trim();
      return `${String(index + 1)}\n${srtTime(cue.startMs)} --> ${srtTime(cue.endMs)}\n${text}\n`;
    })
    .join("\n");
}

/** WebVTT text for a downloadable subtitle file. */
export function toVtt(cues: readonly SubtitleCue[]): string {
  return `WEBVTT\n\n${toSrt(cues).replace(/(\d{2}:\d{2}:\d{2}),(\d{3})/g, "$1.$2")}`;
}

/** The cues of the part of a transcript inside [startMs, endMs), re-timed from 0. */
export function cuesForClip(
  segments: readonly SubtitleCue[],
  startMs: number,
  endMs: number,
): SubtitleCue[] {
  return segments
    .filter((segment) => segment.endMs > startMs && segment.startMs < endMs)
    .map((segment) => ({
      startMs: Math.max(segment.startMs, startMs) - startMs,
      endMs: Math.min(segment.endMs, endMs) - startMs,
      text: segment.text,
    }))
    .filter((cue) => cue.endMs > cue.startMs);
}

export interface RenderRequest {
  readonly input: string;
  readonly output: string;
  readonly workDir: string;
  readonly startMs: number;
  readonly endMs: number;
  readonly source: { readonly width: number; readonly height: number; readonly hasAudio: boolean };
  readonly aspect: AspectRatio;
  readonly cropX: number;
  readonly subtitles: readonly SubtitleCue[] | null;
  /** Hard cap of the output file (FFmpeg stops writing beyond it). */
  readonly maxBytes: number;
  readonly timeoutMs: number;
  readonly signal?: AbortSignal;
}

/** Cuts, reframes and encodes one clip to H.264/AAC MP4 (fast start). */
export async function renderClip(tools: MediaTools, request: RenderRequest): Promise<void> {
  const crop = reframeCrop(
    request.source.width,
    request.source.height,
    request.aspect,
    request.cropX,
  );
  const size = OUTPUT_SIZES[request.aspect];
  const filters = [
    `crop=${String(crop.width)}:${String(crop.height)}:${String(crop.x)}:${String(crop.y)}`,
    `scale=${String(size.width)}:${String(size.height)}`,
    "setsar=1",
  ];
  if (request.subtitles !== null && request.subtitles.length > 0) {
    // A generated file name in our own scratch directory: nothing to escape. libass
    // reads it as a local file; force_style picks a font with Arabic glyphs.
    await writeFile(join(request.workDir, "subtitles.srt"), toSrt(request.subtitles), "utf8");
    filters.push(
      "subtitles=filename=subtitles.srt:charenc=UTF-8:force_style='FontName=DejaVu Sans,FontSize=16,Outline=1,Shadow=0,MarginV=40'",
    );
  }
  const durationSeconds = ((request.endMs - request.startMs) / 1000).toFixed(3);
  await runMediaTool(
    tools.ffmpeg,
    [
      "-nostdin",
      "-hide_banner",
      "-v",
      "error",
      ...LOCAL_ONLY,
      "-ss",
      (request.startMs / 1000).toFixed(3),
      "-i",
      file(request.input),
      "-t",
      durationSeconds,
      "-vf",
      filters.join(","),
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-crf",
      "23",
      "-pix_fmt",
      "yuv420p",
      ...(request.source.hasAudio ? ["-c:a", "aac", "-b:a", "128k"] : ["-an"]),
      "-movflags",
      "+faststart",
      "-threads",
      String(tools.threads),
      "-fs",
      String(request.maxBytes),
      "-y",
      file(request.output),
    ],
    {
      timeoutMs: request.timeoutMs,
      cwd: request.workDir,
      ...(request.signal === undefined ? {} : { signal: request.signal }),
    },
  );
}

/**
 * Checks a rendered file before it is stored: a readable MP4 with an H.264 video stream
 * of the expected size, and a duration within half a second of what was asked.
 */
export async function verifyRender(
  tools: MediaTools,
  path: string,
  expected: { readonly durationMs: number; readonly aspect: AspectRatio },
  options: { readonly timeoutMs: number; readonly signal?: AbortSignal },
): Promise<MediaInfo | null> {
  let info: MediaInfo;
  try {
    info = await probeMedia(tools, path, options);
  } catch (error) {
    if (error instanceof MediaToolError && (error.code === "aborted" || error.code === "timeout")) {
      throw error;
    }
    return null;
  }
  const size = OUTPUT_SIZES[expected.aspect];
  const ok =
    info.formatName.includes("mp4") &&
    info.hasVideo &&
    info.videoCodec === "h264" &&
    info.width === size.width &&
    info.height === size.height &&
    Math.abs(info.durationMs - expected.durationMs) <= 500;
  return ok ? info : null;
}
